import jinja2

template_source = """
<div>
  {% for group in groups %}
    <h2>{{ group['name'] }}</h2>
    <ul>
    {% for task in group['tasks'] %}
      <li>{{ task['description'] }}</li>
    {% endfor %}
    </ul>
  {% endfor %}
</div>
"""

template = jinja2.Template(template_source, autoescape=False)

def render_group(group):
    group['tasks'] = [task['description'] for task in group['tasks']]

    return template.render(groups=[group])
